/* THESIS: Skills are the unit of work; the graph reveals execution and data dependencies.
 * OWN-WORLD: Existing Bakery Geist, fog/ink surfaces, hairlines and cobalt selection.
 * STORY: Choose a skill, bind an agent, connect inputs, validate and publish a revision.
 * FIRST VIEWPORT: Compact rail, searchable skill shelf, working canvas, contextual inspector.
 * FORM: Brief-pinned canvas plus inspector; outline on phones. Existing world, no concept seed.
 * Static design material: all records, runs, connections and conversations are illustrative.
 */
import {writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const dir = fileURLToPath(new URL('.', import.meta.url));
const v = r => `var(--color-light-${r})`;
const C={bg:v('canvas'),surface:v('surface'),subtle:v('subtle'),fg:v('fg'),muted:v('fg-secondary'),border:v('border'),control:v('control'),accent:v('accent'),selected:v('accent-surface'),green:'var(--color-success)',greenBg:'var(--color-success-surface)',red:'var(--color-destructive)',redBg:'var(--color-destructive-surface)',amber:'var(--color-warning)',amberBg:'var(--color-warning-surface)'};
const esc=x=>String(x).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const paths={flow:'M4 3h6v6H4z M14 15h6v6h-6z M7 9v9h7 M14 3h6v6h-6z M17 9v6',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3z M12 6v16',agent:'M5 7h14v12H5z M9 12h.01 M15 12h.01 M9 16h6 M12 3v4 M2 11v4 M22 11v4',plus:'M12 5v14 M5 12h14',chev:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',code:'m8 6-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',chat:'M3 4h18v13H9l-6 4z',loop:'M5 7a8 8 0 0 1 14 0 M19 3v4h-4 M19 17a8 8 0 0 1-14 0 M5 21v-4h4',branch:'M7 3v12a4 4 0 0 0 4 4h6 M7 7h8a4 4 0 0 0 4-4 M4 3h6 M17 16l3 3-3 3',play:'m7 4 14 8-14 8z',link:'M9 15l6-6 M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0 M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',arrow:'M4 12h16 m-6-6 6 6-6 6',upload:'M12 16V3 m-5 5 5-5 5 5 M4 16v5h16v-5',download:'M12 3v13 m-5-5 5 5 5-5 M4 17v4h16v-4',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',alert:'m12 3 10 18H2z M12 9v5 M12 17h.01',close:'m6 6 12 12 M6 18 18 6',more:'M5 12h.01 M12 12h.01 M19 12h.01',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',undo:'M3 10h11a6 6 0 0 1 0 12 M7 5l-5 5 5 5',folder:'M3 5h7l2 3h9v13H3z',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',shield:'M12 2 3 6v7c0 4 9 9 9 9s9-5 9-9V6z m-5 10 3 3 5-6'};
const icon=(name,size=18,color='currentColor')=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="${color}" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0"><path d="${paths[name]||paths.flow}"/></svg>`;
const text=(s,size=14,color=C.fg,weight=400,extra='')=>`<div style="font-size:${size}px;line-height:${size<=14?20:size+8}px;font-weight:${weight};color:${color};${extra}">${esc(s)}</div>`;
const mono=(s,color=C.muted)=>`<div style="font-family:Geist Mono;font-size:12px;line-height:20px;color:${color}">${esc(s)}</div>`;
const row=(content,style='')=>{if(content.startsWith('<svg'))content=content.replace('display:flex;flex-direction:column;gap:6px;','display:flex;flex-direction:column;gap:6px;flex:1;min-width:0;');return `<div style="display:flex;align-items:center;gap:8px;${style}">${content}</div>`;};
const col=(content,style='')=>`<div style="display:flex;flex-direction:column;gap:6px;${style}">${content}</div>`;
const badge=(label,tone='muted')=>{let colors={muted:[C.muted,C.subtle],blue:[C.accent,C.selected],green:[C.green,C.greenBg],red:[C.red,C.redBg],amber:[C.amber,C.amberBg]}[tone];return `<div style="display:flex;align-items:center;padding:3px 7px;border-radius:4px;font-size:12px;line-height:18px;color:${colors[0]};background:${colors[1]};white-space:nowrap">${esc(label)}</div>`;};
const btn=(label,{primary=false,ic,quiet=false}={})=>`<div style="display:flex;align-items:center;justify-content:center;gap:7px;height:36px;padding:0 12px;border:${quiet?'0':'1px'} solid ${primary?C.fg:C.border};border-radius:4px;background:${primary?C.fg:quiet?'transparent':C.surface};color:${primary?C.surface:C.fg};font-size:13px;line-height:20px;font-weight:500;white-space:nowrap">${ic?icon(ic,16,primary?C.surface:C.fg):''}${esc(label)}</div>`;
const field=(label,value,help='',ic='down')=>col(text(label,13,C.fg,500)+row(text(value,14,C.fg,400,'flex:1;min-width:0')+icon(ic,16,C.muted),`min-height:40px;padding:9px 11px;border:1px solid ${C.control};border-radius:4px;background:${C.surface}`)+(help?text(help,12,C.muted):''),'gap:7px');
const note=(title,desc,tone='blue')=>{const color=tone==='red'?C.red:tone==='amber'?C.amber:C.accent;const bg=tone==='red'?C.redBg:tone==='amber'?C.amberBg:C.selected;return row(icon(tone==='blue'?'flow':'alert',18,color)+col(text(title,13,color,500)+text(desc,12,color)),`align-items:flex-start;padding:12px;background:${bg};border-radius:6px;gap:10px`);};
const boards=[];
function board(key,name,width=1440,height=900,dark=false){let b={key,name,width,height,dark,chunks:[]};boards.push(b);return b;}
function add(b,key,parent,html){b.chunks.push({key,parent,html});return key;}
const shell=(b,title,tab='Canvas',status='Draft · v4',extra='')=>{
 add(b,'head',null,row(row(`<img src="paper-asset://~/PersonalDevelopment/bakery/assets/brand/favicon-32.png" style="width:24px;height:24px"/>`+text('Bakery',16,C.fg,600)+text('/',16,C.muted)+text('Workflows',14,C.muted)+icon('chev',14,C.muted)+text(title,14,C.fg,500),'gap:14px;flex:1')+badge(status,status.includes('invalid')?'red':'muted')+btn('Export',{ic:'download'})+btn('Publish',{primary:true}),`width:1440px;height:64px;padding:0 24px;border-bottom:1px solid ${C.border};background:${C.surface};flex-shrink:0;gap:16px`));
 add(b,'bar',null,row(['Canvas','Outline','JSON','Runs'].map(s=>`<div style="display:flex;align-items:center;gap:6px;padding:7px 11px;border-radius:4px;font-size:13px;font-weight:${s===tab?500:400};color:${s===tab?C.accent:C.muted};background:${s===tab?C.selected:'transparent'}">${s===tab?icon(s==='JSON'?'code':s==='Runs'?'play':'flow',16):''}${s}</div>`).join('')+text(extra||'All changes saved',12,C.muted,400,'flex:1;padding-left:16px')+btn('Undo',{ic:'undo',quiet:true})+btn('Validate',{ic:'check'})+btn('Designer',{ic:'chat'}),`height:52px;width:1440px;padding:0 24px;border-bottom:1px solid ${C.border};background:${C.surface};flex-shrink:0;gap:4px`));
 add(b,'body',null,`<div layer-name="Workspace" style="display:flex;flex:1;min-height:0;width:1440px;background:${C.surface}"></div>`);
 add(b,'rail','body',col('',`width:56px;height:100%;flex-shrink:0;padding:16px 8px;gap:12px;border-right:1px solid ${C.border};background:${C.bg}`));
 ['grid','folder','chat','flow','book','settings'].forEach((s,i)=>add(b,`nav${i}`,'rail',row(icon(s,20,i===3?C.accent:C.muted),`width:40px;height:40px;justify-content:center;background:${i===3?C.selected:'transparent'};border-radius:4px`)));
 add(b,'foot',null,row(text('Design prototype · illustrative data',12,C.muted)+text('Personal / Bakery',12,C.muted,400,'flex:1;text-align:center')+text('Skills stay pinned to a published revision',12,C.muted),`height:32px;min-height:32px;width:1440px;padding:0 20px;border-top:1px solid ${C.border};background:${C.surface};justify-content:space-between`));
};
function pane(b,key,width,{bg=C.surface,pad=20,border=true,parent='body'}={}){return add(b,key,parent,`<div layer-name="${key}" style="display:flex;flex-direction:column;width:${width}px;flex-shrink:0;height:fit-content;min-height:0;padding:${pad}px;gap:16px;background:${bg};${border?`border-right:1px solid ${C.border};`:''}"></div>`);}
const section=(b,key,parent,title,desc='')=>add(b,key,parent,col(text(title,16,C.fg,600)+(desc?text(desc,13,C.muted):'')));
function library(b,parent='shelf'){
 section(b,'shelfhead',parent,'Add a step','Start with a skill from your library.');
 add(b,'search',parent,row(icon('search',16,C.muted)+text('Search skills and actions',13,C.muted),`height:40px;padding:10px;border:1px solid ${C.control};border-radius:4px`));
 add(b,'shelftabs',parent,row(badge('Skills','blue')+text('Control flow',13,C.muted)+text('Services',13,C.muted),'gap:10px'));
 const skills=[['Research','rpi.research','Turn a question into evidence.'],['Implementation','harness.implement','Build from an accepted plan.'],['Independent review','review.independent','Review the exact candidate.'],['Repair findings','harness.repair','Resolve findings, then recheck.']];
 skills.forEach(([name,action,desc],i)=>add(b,`skill${i}`,parent,col(row(icon('book',18,C.muted)+text(name,13,C.fg,500)+text('⠿',16,C.muted,400,'flex:1;text-align:right'))+text(desc,12,C.muted)+row(mono(action)+badge('v1')),`padding:12px 0;border-bottom:1px solid ${C.border};gap:7px`)));
 add(b,'createskill',parent,btn('Create a skill',{ic:'plus'}));
 add(b,'shelfnote',parent,text('Drag onto the canvas, or select a skill to choose where it goes.',12,C.muted));
}
function graph(b,parent,{width=752,height=600,loop=false,review=false}={}){
 add(b,'graph',parent,`<div layer-name="Workflow canvas" style="display:flex;position:relative;flex:1;min-height:${height}px;width:${width}px;background:${C.bg};border-radius:0"></div>`);
 add(b,'graphlabel','graph',row(badge(review?'Pinned · v3':'Software delivery','muted')+text(loop?'Bounded control flow':'5 steps · 3 skills · 1 connection',12,C.muted),`position:absolute;left:24px;top:22px;gap:12px`));
 const x=loop?90:Math.round((width-272)/2);const nodes=loop?[[x,82,'Input ready','Start','flow'],[x,198,'Independent review','Skill · review.independent','book'],[x,424,'Repair findings','Skill · harness.repair','book'],[x,556,'Candidate ready','Output · evidence','check']]:[[x,82,'Ticket received','GitHub issue · ready label','link'],[x,206,'Research','Skill · rpi.research · v1','book'],[x,330,'Implementation','Skill · harness.implement · v1','book'],[x,454,'Independent review','Skill · review.independent · v1','book'],[x,578,'Candidate ready','Output · checked revision','check']];
 const points=loop?[[218,174,218,198],[218,290,218,424],[218,516,218,556]]:[[x+136,174,x+136,206],[x+136,298,x+136,330],[x+136,422,x+136,454],[x+136,546,x+136,578]];
 add(b,'edges','graph',`<svg width="${width}" height="${height+80}" viewBox="0 0 ${width} ${height+80}" style="position:absolute;left:0;top:0" fill="none">${points.map(([x1,y1,x2,y2])=>`<path d="M${x1} ${y1} L${x2} ${y2}" stroke="${C.control}" stroke-width="1.5"/><path d="m${x2-4} ${y2-6} 4 6 4-6" stroke="${C.control}" stroke-width="1.5"/>`).join('')}</svg>`);
 if(loop){add(b,'loopgroup','graph',`<div layer-name="Repeat container" style="display:flex;flex-direction:column;position:absolute;left:62px;top:337px;width:452px;height:202px;padding:14px;border:1px dashed ${C.accent};border-radius:8px;background:${C.selected}">${row(icon('loop',16,C.accent)+text('Repeat until checks pass',13,C.accent,500)+badge('Max 2 cycles','blue'))}</div>`);}
 nodes.forEach(([nx,ny,title,sub,ic],i)=>add(b,`node${i}`,'graph',col(row(icon(ic,18,(i===2&&!loop)?C.accent:C.muted)+text(title,14,C.fg,600)+text(review&&i<2?'✓':`${i+1}`,12,review&&i<2?C.green:C.muted,400,'flex:1;text-align:right'))+text(sub,12,C.muted)+row(mono(i===0?'issue → taskId':i===nodes.length-1?'candidate → ArtifactRef':'input → ArtifactRef')+icon('more',16,C.muted),'justify-content:space-between'),`position:absolute;left:${nx}px;top:${ny}px;width:272px;height:92px;padding:12px 14px;background:${C.surface};border:1px solid ${i===2&&!loop?C.accent:C.control};border-radius:6px;gap:6px`)));
 if(loop){add(b,'loopbranch','graph',col(text('Any blocking findings?',13,C.fg,500)+row(badge('Yes → repair','blue')+badge('No → candidate','green')),`position:absolute;left:390px;top:210px;width:222px;gap:12px`));add(b,'loopback','graph',`<svg width="${width}" height="680" viewBox="0 0 ${width} 680" style="position:absolute;left:0;top:0" fill="none"><path d="M362 470H476V285H362" stroke="${C.accent}" stroke-width="1.5" stroke-dasharray="5 4"/><path d="m368 281-6 4 6 4" stroke="${C.accent}" stroke-width="1.5"/></svg>`);}
 add(b,'zoom','graph',row(btn('−',{quiet:true})+text('100%',12,C.muted)+btn('+',{quiet:true})+btn('Fit',{quiet:true}),`position:absolute;left:20px;bottom:16px;height:38px;border:1px solid ${C.border};background:${C.surface};border-radius:6px;gap:0`));
}
function inspector(b,parent='inspector'){
 add(b,'inspecthead',parent,row(col(text('Implementation',16,C.fg,600)+mono('harness.implement'))+icon('close',18,C.muted),'justify-content:space-between'));
 add(b,'inspecttabs',parent,row(badge('Setup','blue')+text('Inputs',13,C.muted)+text('Limits',13,C.muted),'gap:22px'));
 add(b,'bindskill',parent,field('Skill','Implementation · v1','Published · Library / RPI'));
 add(b,'bindagent',parent,field('Agent','Builder · revision 3','Inherited from Software delivery'));
 add(b,'model',parent,col(row(text('Execution',13,C.muted)+text('Worker · Linux pool',13,C.fg,500),'justify-content:space-between')+row(text('Harness',13,C.muted)+text('Codex',13,C.fg),'justify-content:space-between')+row(text('Provider / model',13,C.muted)+text('OpenAI · GPT-5.6 Sol',13,C.fg),'justify-content:space-between')+row(text('Required tools',13,C.muted)+text('Git · Shell',13,C.fg),'justify-content:space-between')+btn('Override agent for this step',{quiet:true}),'gap:10px'));
 add(b,'mapping',parent,field('Plan artifact','Research → artifact','ArtifactRef · output from an earlier step','link'));
 add(b,'mapping2',parent,field('Repository','Workflow input → repositoryId','','link'));
 add(b,'permission',parent,note('Repository access ready','GitHub · MarkTripoli/bakery · write code'));
 add(b,'stepfooter',parent,row(btn('Open skill',{ic:'book'})+btn('More',{ic:'more'}),'justify-content:space-between'));
}
