// Phone screens keep the same tasks, using an ordered outline and full-width fields.
function phone(key,title,tab='Outline',action='Save draft'){
 const p=board(key+'-phone',`${boards.find(b=>b.key===key).name.replace(' · Desktop','')} · Phone`,390,900);p.phoneOf=key;
 add(p,'phonehead',null,row(icon('chev',18,C.muted)+col(text(title,16,C.fg,600)+text('Personal · Software delivery',12,C.muted))+icon('more',20,C.muted),`width:390px;min-height:76px;padding:16px 20px;border-bottom:1px solid ${C.border};gap:12px;justify-content:space-between`));
 add(p,'phonetabs',null,row(['Outline','Setup','JSON','Designer'].map(s=>`<div style="display:flex;align-items:center;justify-content:center;height:44px;flex:1;font-size:13px;color:${tab===s?C.accent:C.muted};background:${tab===s?C.selected:'transparent'};border-radius:4px">${s}</div>`).join(''),`padding:8px 12px;width:390px;border-bottom:1px solid ${C.border};gap:2px`));
 add(p,'phonebody',null,col('',`width:390px;padding:20px;gap:20px;flex:1;background:${C.surface}`));
 add(p,'phoneactions',null,row(btn('More',{ic:'more'})+btn(action,{primary:true}),`width:390px;min-height:80px;padding:16px 20px 20px;border-top:1px solid ${C.border};background:${C.surface};justify-content:space-between`));
 add(p,'phonefoot',null,text('Design prototype · illustrative data',12,C.muted,400,'padding:0 20px 16px'));
 return p;
}
