for(const key of ['json','states']){const d=boards.find(d=>d.key===key);d.chunks.find(c=>c.key==='head').html=d.chunks.find(c=>c.key==='head').html.replace(btn('Publish',{primary:true}),disabledPublish);if(key==='states')d.chunks.find(c=>c.key==='bar').html=d.chunks.find(c=>c.key==='bar').html.replace('All changes saved','Resolve shared-draft conflict before publishing');}
const exchange=boards.find(d=>d.key==='exchange');exchange.chunks.find(c=>c.key==='head').html=exchange.chunks.find(c=>c.key==='head').html.replace(btn('Publish',{primary:true}),btn('Close import'));exchange.chunks.find(c=>c.key==='bar').html=exchange.chunks.find(c=>c.key==='bar').html.replace('All changes saved','Original import file retained');
const order=['library','studio','skill','control','designer','json-live','json','exchange','services','publish','run','states','studio-dark','packaged','repositories','coordination','routing'];
for(const d of boards){d.order=order.indexOf(d.phoneOf||d.key);d.chunks=d.chunks.map(c=>({...c,html:c.html.replace('display:flex;flex:1;min-height:0;width:1440px','display:flex;flex:0 0 auto;min-height:752px;height:fit-content;align-items:stretch;width:1440px').replace('height:100%;flex-shrink:0;padding:16px 8px','align-self:stretch;flex-shrink:0;padding:16px 8px')}));}
const lib=boards.find(d=>d.key==='library');lib.chunks.find(c=>c.key==='head').html=row(row(`<img src="paper-asset://~/PersonalDevelopment/bakery/assets/brand/favicon-32.png" style="width:24px;height:24px"/>`+text('Bakery',16,C.fg,600)+text('/',16,C.muted)+text('Workflows',14,C.fg,500),'gap:14px;flex:1')+text('Personal workspace',13,C.muted),`width:1440px;height:64px;padding:0 24px;border-bottom:1px solid ${C.border};background:${C.surface}`);lib.chunks.find(c=>c.key==='bar').html=row(badge('Organization','blue')+text('Bakery-provided · Locked',13,C.muted)+text('Archived',13,C.muted),`height:52px;width:1440px;padding:0 24px;border-bottom:1px solid ${C.border};gap:24px`);
const run=boards.find(d=>d.key==='run');run.chunks.find(c=>c.key==='head').html=run.chunks.find(c=>c.key==='head').html.replace(btn('Publish',{primary:true}),btn('Stop run'));run.chunks.find(c=>c.key==='bar').html=run.chunks.find(c=>c.key==='bar').html.replace(btn('Undo',{ic:'undo',quiet:true}),'').replace(btn('Validate',{ic:'check'}),btn('Open draft',{ic:'flow'}));
for(const key of ['studio','studio-phone']){const orig=boards.find(d=>d.key===key);const dark=structuredClone(orig);dark.key+='-dark';dark.name+=' · Dark';dark.dark=true;dark.order=12;dark.chunks=dark.chunks.map(c=>({...c,html:c.html.replaceAll('--color-light-','--color-dark-').replaceAll('--color-success-surface','--color-dark-success-surface').replaceAll('--color-success)','--color-dark-success)').replaceAll('--color-warning-surface','--color-dark-warning-surface').replaceAll('--color-warning)','--color-dark-warning)').replaceAll('--color-destructive-surface','--color-dark-critical-surface').replaceAll('--color-destructive)','--color-dark-critical)')}));boards.push(dark);}

export {boards,C,icon,text,mono,row,col,badge,btn,field,note,board,add,pane,shell,section,graph,inspector,library};
export function save(){for(const b of boards)for(const c of b.chunks)c.html=c.html.replaceAll('style="','style="font-family:Geist;').replaceAll('font-family:Geist Mono','font-family:\'Geist Mono\'');writeFileSync(dir+'paper-source.json',JSON.stringify(boards,null,2));}
